.dictionary-audio-source { box-sizing: border-box; max-width: 100%; padding: .2rem 1.3rem .2rem .45rem; border: 1px solid var(--line); border-radius: 5px; background: var(--surface); color: var(--secondary); font: inherit; cursor: pointer; }
