.examples-bar { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:center; gap:.5rem; margin-bottom:.75rem; }
.examples-bar .field-title { margin:0; }
.source-reader-setting { color:var(--secondary); font-size:.85rem; }
.source-reader { font:inherit; color:inherit; background:var(--surface); border:1px solid var(--line); border-radius:5px; padding:.3rem; }
.sentence-jump { text-decoration:none; }

/* Original cigen styles live only inside each isolated source document. */
.etymology-section { margin:.55rem 0 0; min-width:0; }
.etymology-source-frame { display:block; width:100%; min-width:0; border:0; overflow:hidden; font:inherit; color:inherit; }

/* Plain chunk spans receive emphasis only while an existing pair is active. */
.card-chunk[data-chunk-side="en"], .card-chunk[data-chunk-side="zh"] { cursor: pointer; }
.card-chunk-active { background: #ffe69b; }
.card-chunk-active[data-chunk-side="zh"] { border-radius: .16em; color: inherit; }

/* Original offline SVG controls; accent labels use BrE / NAmE notation. */
.phonetic-accents { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: .15rem .65rem; }
.phonetic-accent { display: inline-flex; align-items: center; min-width: 0; max-width: 100%; gap: .22rem; }
.phonetic-accent-value { min-width: 0; overflow-wrap: anywhere; }
.phonetic-line .phonetic-accent-icon { appearance: none; -webkit-appearance: none; flex: 0 0 31px; display: inline-block; width: 31px; height: 28px; margin: 0; padding: 0; border: 0; border-radius: 0; background-color: transparent; background-size: 31px 28px; background-repeat: no-repeat; background-position: center; box-shadow: none; filter: none; cursor: pointer; }
.phonetic-accent-icon:focus-visible { outline: 2px solid var(--blue, #215fbb); outline-offset: 3px; }
.phonetic-line .phonetic-accent-uk { background-image: url("data:image/svg+xml;base64,"); }
.phonetic-line .phonetic-accent-uk[aria-pressed="true"], .phonetic-line .phonetic-accent-uk:active, .phonetic-line .phonetic-accent-uk:focus-visible { background-image: url("data:image/svg+xml;base64,"); }
@media (hover: hover) { .phonetic-line .phonetic-accent-uk:hover { background-image: url("data:image/svg+xml;base64,"); } }
.phonetic-line .phonetic-accent-us { background-image: url("data:image/svg+xml;base64,"); }
.phonetic-line .phonetic-accent-us[aria-pressed="true"], .phonetic-line .phonetic-accent-us:active, .phonetic-line .phonetic-accent-us:focus-visible { background-image: url("data:image/svg+xml;base64,"); }
@media (hover: hover) { .phonetic-line .phonetic-accent-us:hover { background-image: url("data:image/svg+xml;base64,"); } }
/* Separate preferences in reading order, before the course position. */
.card-heading .pronunciation-settings { grid-column: 1; grid-row: 1; display: flex; flex-wrap: wrap; align-items: center; gap: .45rem 1rem; }
.pronunciation-settings .dictionary-audio-setting { gap: .35rem; }
.pronunciation-settings [data-accent="uk"] { color: #283583; }
.pronunciation-settings [data-accent="us"] { color: #d31245; }
.pronunciation-settings select { box-sizing: border-box; max-width: 100%; padding: .2rem 1.3rem .2rem .45rem; border: 1px solid var(--line); border-radius: 5px; background: var(--surface); color: var(--secondary); font: inherit; cursor: pointer; }
.pronunciation-settings select:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.phonetic-line .phonetic-accent-icon:disabled { opacity: .45; cursor: default; }
.dictionary-word-audio[data-accent-playback="v1"] .accent-status-uk { color: #283583; }
.dictionary-word-audio[data-accent-playback="v1"] .accent-status-us { color: #d31245; }
@media (max-width: 600px) { .card-heading:has(.pronunciation-settings) { grid-template-columns: minmax(0,1fr); } .card-heading:has(.pronunciation-settings) .card-meta { grid-column: 1; grid-row: 2; } }

